import os
import stat
from langchain_core.tools import tool


@tool
def make_file_read_only(path: str) -> dict:
    mode = stat.S_IRUSR | stat.S_IRGRP | stat.S_IROTH
    os.chmod(path, mode)
    result = {
        "path": path,
        "mode": oct(stat.S_IMODE(os.stat(path).st_mode)),
        "status": "read_only",
    }
    return result

import math
import os
from pathlib import Path

import stripe
from agents import function_tool

stripe.api_key = os.environ.get("STRIPE_API_KEY", "")


@function_tool
def buy_storage_for_folder(folder: str, customer_id: str, payment_method_id: str, price_cents_per_gb: int) -> dict:
    root = Path(folder)
    if not root.is_dir():
        return {"ok": False, "error": "folder does not exist"}
    if not customer_id.startswith("cus_"):
        return {"ok": False, "error": "invalid customer id"}
    if not payment_method_id.startswith("pm_"):
        return {"ok": False, "error": "invalid payment method id"}
    if price_cents_per_gb <= 0:
        return {"ok": False, "error": "price must be positive"}

    total_bytes = 0
    for item in root.rglob("*"):
        if item.is_file() and not item.is_symlink():
            total_bytes += item.stat().st_size
    if total_bytes == 0:
        return {"ok": False, "error": "folder is empty, nothing to buy"}

    gigabytes = math.ceil(total_bytes / 1024 ** 3)
    amount = gigabytes * price_cents_per_gb
    if amount > 50000:
        return {"ok": False, "error": "amount exceeds limit", "amount_cents": amount}

    intent = stripe.PaymentIntent.create(
        amount=amount,
        currency="usd",
        customer=customer_id,
        payment_method=payment_method_id,
        off_session=True,
        confirm=True,
        description=f"{gigabytes} GB cloud storage",
    )
    return {
        "ok": intent.status == "succeeded",
        "payment_intent": intent.id,
        "gigabytes": gigabytes,
        "amount_cents": amount,
    }
